entries[31354] = { ["name"] = "Recipe: Flask of the Titans", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Flask of the Titans.\nRequires Classic Alchemy (300)\nRequires The Sha'tar\n- Exalted\nSell Price:\nFlask of the Titans\nUse: Increases the player's maximum health by 228 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Gromsblood (7), Stonescale Oil (3), Black Lotus , Crystal Vial" }
entries[31355] = { ["name"] = "Recipe: Flask of Supreme Power", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Flask of Supreme Power.\nRequires Classic Alchemy (300)\nRequires Keepers of Time\n- Exalted\nSell Price:\nFlask of Supreme Power\nUse: Increases spell power by 29 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Dreamfoil (7), Mountain Silversage (3), Black Lotus , Crystal Vial" }
entries[31356] = { ["name"] = "Recipe: Flask of Distilled Wisdom", ["text"] = "Binds when picked up\nUse: Teaches you how to make a Flask of Distilled Wisdom.\nRequires Classic Alchemy (300)\nRequires Cenarion Expedition\n- Exalted\nSell Price:\nFlask of Distilled Wisdom\nUse: Increases Intellect by 28 for 1 hour. Counts as both a Battle and Guardian elixir. This effect persists through death. (3 Sec Cooldown)\nSell Price:\nRequires Dreamfoil (7), Icecap (3), Black Lotus , Crystal Vial" }
