entries[31358] = { ["name"] = "Design: Dawnstone Crab", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Dawnstone Crab.\nRequires Outland Jewelcrafting (70)\nRequires Thrallmar\n- Revered\nSell Price:\nFigurine - Dawnstone Crab\nBinds when picked up\nUnique-Equipped\nTrinket\n+ 5 Dodge\nUse: Increases dodge by 21 for 20 sec. (2 Min Cooldown)\nRequires Outland Jewelcrafting (70)\nSell Price:\nRequires Khorium Bar (4), Dawnstone (2), Golden Draenite (4)\nOptional Reagents: Optional Reagent Slot (#49)" }
