entries[31829] = { ["name"] = "Reins of the Cobalt Riding Talbuk", ["text"] = "Binds when picked up\nMount\n(Account-wide)\nRequires any Horde race\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Cobalt Riding Talbuk.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Mag'har\n- Exalted\n\n\"The orcs once hunted these graceful herd animals as part of the om'riggor rite of passage ceremony.\"\nVendor:\nProvisioner Nasela\nZone:\nNagrand, Outland\nFaction:\nThe Mag'har - Exalted\nCost:\n\nVendor:\nTrader Narasu\nZone:\nNagrand, Outland\nFaction:\nThe Kurenai - Exalted\nCost:" }
